function EXTRA(R,ICON){
 /* hook: the truck and its two filler caps */
 ICON.emTruck=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${EM_box(0,0,380,160,{fill:'#FFFFFF',st:EM_GREY,sw:3,r:18})}
  <rect x="30" y="34" width="110" height="86" rx="12" fill="${BLU}"/><rect x="44" y="46" width="60" height="34" rx="5" fill="#E7F5FF"/>
  <rect x="146" y="22" width="206" height="98" rx="6" fill="#DEE2E6" stroke="${EM_STEEL}" stroke-width="3"/>${EM_T(249,80,'diesel truck',{fs:24,fw:800,a:'middle',fill:EM_STEEL})}
  <circle cx="74" cy="128" r="20" fill="#343A40"/><circle cx="210" cy="128" r="20" fill="#343A40"/><circle cx="300" cy="128" r="20" fill="#343A40"/>
  <circle cx="124" cy="104" r="8" fill="#212529"/><circle cx="140" cy="104" r="8" fill="${BLU}" stroke="#FFFFFF" stroke-width="2"/></g>`;
 ICON.emCaps=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${EM_box(0,0,380,160,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}
  <circle cx="90" cy="70" r="44" fill="#212529"/><circle cx="90" cy="70" r="28" fill="none" stroke="#495057" stroke-width="4"/>${EM_T(90,140,'diesel',{fs:24,fw:800,a:'middle'})}
  <circle cx="250" cy="70" r="44" fill="#1C7ED6"/><circle cx="250" cy="70" r="28" fill="none" stroke="#A5D8FF" stroke-width="4"/>${EM_T(250,140,'urea solution',{fs:24,fw:800,a:'middle',fill:'#1C7ED6'})}</g>`;
 /* recap pictures, each about 420 × 330 */
 ICON.emR1=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${EM_cyl(60,30,140,300,250,44)}${EM_flame(130,140,110,'#FFA94D')}
  ${EM_mol(310,70,'CO₂',BLU,22)}${EM_mol(310,130,'H₂O',BLU,22)}${EM_arrow(270,100,214,120,BLU,4)}
  ${EM_T(310,214,'cooler',{fs:26,fw:800,a:'middle',fill:GRN})}${EM_T(310,256,'NOx ↓',{fs:30,fw:800,a:'middle',fill:GRN})}</g>`;
 ICON.emR2=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${EM_brick(20,20,150,96,PUR)}${EM_T(190,62,'petrol, λ = 1:',{fs:24,fw:800,fill:PUR})}${EM_T(190,96,'one TWC',{fs:24,fw:700,fill:EM_GREY})}
  ${EM_T(10,176,'lean diesel, in order',{fs:24,fw:800,fill:ORG})}
  ${['DOC','DPF','urea','SCR','ASC'].map((t,i)=>EM_box(i*84,200,72,90,{fill:i===2?'#EBFBEE':'#FFF4E6',st:i===2?GRN:ORG,sw:3,r:8})+EM_T(i*84+36,254,t,{fs:22,fw:800,a:'middle'})).join('')}</g>`;
 ICON.emR3=(x,y)=>`<g transform="translate(${x-210} ${y-165})">
  ${EM_box(0,0,200,150,{fill:'#E7F5FF',st:BLU,sw:3})}${EM_T(100,50,'NDIR',{fs:26,fw:800,a:'middle',fill:BLU})}${EM_T(100,96,'CO, CO₂',{fs:24,fw:700,a:'middle'})}
  ${EM_box(220,0,200,150,{fill:'#EBFBEE',st:GRN,sw:3})}${EM_T(320,50,'CLD',{fs:26,fw:800,a:'middle',fill:GRN})}${EM_T(320,96,'NO, NOx',{fs:24,fw:700,a:'middle'})}
  ${EM_box(0,170,200,150,{fill:'#FFF4E6',st:ORG,sw:3})}${EM_T(100,220,'FID',{fs:26,fw:800,a:'middle',fill:ORG})}${EM_T(100,266,'HC in ppmC',{fs:24,fw:700,a:'middle'})}
  ${EM_box(220,170,200,150,{fill:'#F1F3F5',st:EM_GREY,sw:3})}${EM_T(320,220,'smoke',{fs:26,fw:800,a:'middle',fill:EM_SOOT})}${EM_T(320,266,'opacity, Bosch',{fs:24,fw:700,a:'middle'})}</g>`;
}
